pid_t pid = fork();
if (pid === 0) {
    exit(42); // child finishes, becomes a zombie holding exit status 42
} else {
    int status;
    wait(&status);                 // collects the zombie, removes its entry
    int code = WEXITSTATUS(status); // code is now 42
}

